from __future__ import annotations
import base64, csv, json, zlib
from pathlib import Path

BASELINE_B64=""
REC=Path("v4-sec-f34-strict-recovery-output/recovery_bitmask.json")
OUT=Path("v4-sec-f34-strict-recovery-output")
OUT.mkdir(parents=True,exist_ok=True)

base=json.loads(zlib.decompress(base64.b64decode(BASELINE_B64)).decode())
rec=json.loads(REC.read_text(encoding="utf-8"))
if base["target_count"]!=rec["target_count"] or base["target_sha256"]!=rec["target_sha256"]:
    raise RuntimeError("target order/hash mismatch")
if base["snapshots"]!=rec["snapshots"]:
    raise RuntimeError("snapshot mismatch")

def bit_at(b64,i):
    b=base64.b64decode(b64)
    return bool((b[i//8] >> (i%8)) & 1)

rows=[]
detail=[]
for b,r in zip(base["by_snapshot"],rec["by_snapshot"]):
    if b["snapshot_date"]!=r["snapshot_date"]:
        raise RuntimeError("snapshot row mismatch")
    s=b["snapshot_date"]
    d={"snapshot_date":s}
    for fac,key in [("F3","f3_usable_b64"),("F4","f4_usable_b64")]:
        z=b[fac]
        rb64=r[key]
        c_rec=sum(cnt for idx,cnt in z["confirmed_missing_target_index_counts"] if bit_at(rb64,int(idx)))
        u_rec=sum(cnt for idx,cnt in z["unknown_missing_target_index_counts"] if bit_at(rb64,int(idx)))
        cn=int(z["confirmed_n"]); cu0=int(z["confirmed_usable_baseline"]); cu=cu0+c_rec
        un=int(z["unknown_n"]); uu0=int(z["unknown_usable_baseline"]); uu=uu0+u_rec
        umiss=un-uu
        cov=cu/cn if cn else None
        lower=cu/(cn+umiss) if (cn+umiss) else None
        upper=(cu+uu)/(cn+uu) if (cn+uu) else None
        threshold=(4*cn+4)//5  # ceil(0.8*N)
        need=max(0,threshold-cu)
        passed=bool(cu>=threshold)
        d.update({
            f"{fac}_confirmed_n":cn,
            f"{fac}_baseline_usable":cu0,
            f"{fac}_recovered_confirmed":c_rec,
            f"{fac}_final_usable":cu,
            f"{fac}_confirmed_coverage":cov,
            f"{fac}_coverage_pct":100*cov if cov is not None else None,
            f"{fac}_threshold_80_count":threshold,
            f"{fac}_need_for_80":need,
            f"{fac}_pass_80":passed,
            f"{fac}_unknown_n":un,
            f"{fac}_unknown_usable_baseline":uu0,
            f"{fac}_recovered_unknown":u_rec,
            f"{fac}_final_unknown_usable":uu,
            f"{fac}_lower_bound":lower,
            f"{fac}_upper_bound":upper,
            f"{fac}_lower_bound_pct":100*lower if lower is not None else None,
            f"{fac}_upper_bound_pct":100*upper if upper is not None else None,
            f"{fac}_confirmed_missing_outside_target":int(z["confirmed_missing_outside_target"]),
            f"{fac}_unknown_missing_outside_target":int(z["unknown_missing_outside_target"]),
        })
    rows.append(d)
summary={
 "schema":"V4_NEXT1_FINAL_NONFIN_COVERAGE_AFTER_STRICT_SEC_RECOVERY_V1",
 "population":"NONFIN_MAIN",
 "coverage_rule":">=80% confirmed eligibility coverage at every planned snapshot; missing factor is not imputed",
 "existing_corp_action_excluded_tickers":base["excluded_existing_corp_action_tickers"],
 "new_corp_action_lookup_calls":0,
 "formation_2023_opened":False,
 "future_outcomes_used":False,
 "us3700_used":False,
 "target_count":base["target_count"],
 "target_sha256":base["target_sha256"],
 "F3_all_snapshots_pass":all(x["F3_pass_80"] for x in rows),
 "F4_all_snapshots_pass":all(x["F4_pass_80"] for x in rows),
 "F3_min_coverage_pct":min(x["F3_coverage_pct"] for x in rows),
 "F4_min_coverage_pct":min(x["F4_coverage_pct"] for x in rows),
 "rows":rows,
}
(OUT/"final_nonfin_coverage.json").write_text(json.dumps(summary,indent=2),encoding="utf-8")
fields=list(rows[0].keys())
with (OUT/"final_nonfin_coverage.csv").open("w",newline="",encoding="utf-8") as f:
    w=csv.DictWriter(f,fieldnames=fields); w.writeheader(); w.writerows(rows)
print(json.dumps({
 "F3_all_snapshots_pass":summary["F3_all_snapshots_pass"],
 "F4_all_snapshots_pass":summary["F4_all_snapshots_pass"],
 "F3_min_coverage_pct":summary["F3_min_coverage_pct"],
 "F4_min_coverage_pct":summary["F4_min_coverage_pct"],
 "rows":[{k:v for k,v in x.items() if k in ["snapshot_date","F3_confirmed_n","F3_baseline_usable","F3_recovered_confirmed","F3_final_usable","F3_coverage_pct","F3_need_for_80","F3_pass_80","F4_confirmed_n","F4_baseline_usable","F4_recovered_confirmed","F4_final_usable","F4_coverage_pct","F4_need_for_80","F4_pass_80"]} for x in rows]
},indent=2))
